import {Select} from '@/components/nyc-tron/ui/components/Select';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {space,size} from '@/components/nyc-tron/ui/tokens';
export interface ValidationDropdownProps extends Omit<ViewProps,'children'>,ScopedControlProps {
 value:string;choices:readonly {value:string;label:string}[];allowOther:boolean;allowBlank:boolean;
 validation:{status:'valid'|'invalid'|'checking';message?:string};onCommit:(value:string,signal?:AbortSignal)=>unknown;unstyled?:boolean;
}
export function ValidationDropdown({scope='cell-validation',revision=0,...props}:ValidationDropdownProps){
 const {value,choices,allowOther,allowBlank,validation,onCommit:_commit,unstyled=false,disabledReason,style,...rest}=props;
 if(value.length>65536||choices.length>512||new Set(choices.map(c=>c.value)).size!==choices.length||choices.some(c=>c.value.length>8192||!c.label.trim()||c.label.length>1024))throw new RangeError('Invalid validation choices');
 const owner=JSON.stringify([...controlIdentity(scope,revision),disabledReason]),guard=useScopedControl(owner,props,disabledReason!==undefined||validation.status==='checking'),off=guard.pending||disabledReason!==undefined||validation.status==='checking';
 const local=useRef<ReturnType<typeof makeStore>|null>(null);local.current??=makeStore(value);const store=local.current,draft=useStore(store,s=>s.draft);
 useLayoutEffect(()=>{store.setState({draft:value});},[value,owner]);
 const commit=(next:string)=>guard.run('value',(h,s)=>{if(!next&&!h.allowBlank)throw new Error('A value is required');if(next&&!h.allowOther&&!h.choices.some(c=>c.value===next))throw new Error('Choose an allowed list value');return h.onCommit(next,s);});
 return <View {...rest} accessibilityLabel="Cell validation list" style={[{gap:space[1.5]},style]}><Select label="Allowed cell values" value={value} options={[...choices,...(!choices.some(c=>c.value===value)?[{value,label:value?'Current value outside list':'No value',disabled:true}]:[])]} disabled={off||choices.length===0} unstyled={unstyled} onValueChange={commit}/>
 {allowOther?<><TextInput accessibilityLabel="Custom cell value" value={draft} maxLength={65536} editable={!off} onChangeText={draft=>store.setState({draft})} onSubmitEditing={()=>commit(draft)} style={{minHeight:size.touch,padding:space[2]}} {...{className:unstyled?undefined:'text-text border border-border rounded-control'}}/><Button title="Apply custom value" disabled={off||draft===value} unstyled={unstyled} onPress={()=>commit(draft)}/></>:null}
 {allowBlank?<Button title="Clear validated cell" variant="secondary" disabled={off||value===''} unstyled={unstyled} onPress={()=>commit('')}/>:null}<Text accessibilityLiveRegion="polite" {...{className:unstyled?undefined:'text-text'}}>{validation.status}{validation.message?': '+validation.message:''}</Text><ErrorMessage message={guard.error??disabledReason} unstyled={unstyled}/></View>;
}
function makeStore(draft:string){return createStore(()=>({draft}));}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

